    54→// ParseHookEvent translates a Claude Code hook into a normalized lifecycle Event.
    55→// Returns nil if the hook has no lifecycle significance.
    56→func (c *ClaudeCodeAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
    57→	switch hookName {
    58→	case HookNameSessionStart:
    59→		return c.parseSessionStart(stdin)
    60→	case HookNameUserPromptSubmit:
    61→		return c.parseTurnStart(stdin)
    62→	case HookNameStop:
    63→		return c.parseTurnEnd(stdin)
    64→	case HookNameSessionEnd:
    65→		return c.parseSessionEnd(stdin)
    66→	case HookNamePreTask:
    67→		return c.parseSubagentStart(stdin)
    68→	case HookNamePostTask:
    69→		return c.parseSubagentEnd(stdin)
    70→	case HookNamePostTodo:
    71→		// PostTodo is Claude-specific; handled outside the generic dispatcher.
    72→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
    73→	default:
    74→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
    75→	}
    76→}
