   239→// --- Transcript flush sentinel ---
   240→
   241→// stopHookSentinel is the string that appears in Claude Code's hook_progress
   242→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
   243→const stopHookSentinel = "hooks claude-code stop"
   244→
   245→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
   246→// Falls back silently after a timeout.
   247→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
   248→	const (
   249→		maxWait      = 3 * time.Second
   250→		pollInterval = 50 * time.Millisecond
   251→		tailBytes    = 4096
   252→		maxSkew      = 2 * time.Second
   253→	)
   254→
   255→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
   256→
   257→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
   258→	// - File doesn't exist: nothing to poll.
   259→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
   260→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
   261→	//   without firing stop hook).
   262→	const staleThreshold = 2 * time.Minute
   263→	info, err := os.Stat(transcriptPath)
   264→	if err != nil {
   265→		// Most likely the file doesn't exist; other errors (permission, etc.)
   266→		// would also prevent polling, so skip the wait either way.
   267→		return
   268→	}
   269→	fileAge := time.Since(info.ModTime())
   270→	if fileAge > staleThreshold {
   271→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
   272→			slog.Duration("file_age", fileAge),
   273→		)
   274→		return
   275→	}
   276→
   277→	deadline := time.Now().Add(maxWait)
   278→	for time.Now().Before(deadline) {
   279→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
   280→			logging.Debug(logCtx, "transcript flush sentinel found",
   281→				slog.Duration("wait", time.Since(hookStartTime)),
   282→			)
   283→			return
   284→		}
   285→		time.Sleep(pollInterval)
   286→	}
   287→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
   288→		slog.Duration("timeout", maxWait),
   289→	)
   290→}
   291→
   292→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
   293→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
   294→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
   295→	if err != nil {
   296→		return false
   297→	}
   298→	defer f.Close()
   299→
   300→	info, err := f.Stat()
   301→	if err != nil {
   302→		return false
   303→	}
   304→	offset := info.Size() - tailBytes
   305→	if offset < 0 {
   306→		offset = 0
   307→	}
   308→	buf := make([]byte, info.Size()-offset)
   309→	if _, err := f.ReadAt(buf, offset); err != nil {
   310→		return false
   311→	}
   312→
   313→	lines := strings.Split(string(buf), "\n")
   314→	for _, line := range lines {
   315→		line = strings.TrimSpace(line)
   316→		if line == "" || !strings.Contains(line, stopHookSentinel) {
   317→			continue
   318→		}
   319→
   320→		var entry struct {
   321→			Timestamp string `json:"timestamp"`
   322→		}
   323→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
   324→			continue
   325→		}
   326→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
   327→		if err != nil {
   328→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
   329→			if err != nil {
   330→				continue
   331→			}
   332→		}
   333→		// Validate timestamp is within acceptable range:
   334→		// - Not too far in the past (before hook started minus skew)
   335→		// - Not too far in the future (after hook started plus skew)
   336→		lowerBound := hookStartTime.Add(-maxSkew)
   337→		upperBound := hookStartTime.Add(maxSkew)
   338→		if ts.After(lowerBound) && ts.Before(upperBound) {
   339→			return true
   340→		}
   341→	}
   342→	return false
   343→}
